 final BroadcastReceiver homeReceiver=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){if(Intent.ACTION_CLOSE_SYSTEM_DIALOGS.equals(intent.getAction())&&CompanionLifecycle.isHomeReason(intent.getStringExtra("reason")))suspendForHome();}};
